ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'../reports/social-cards-2026-11-11';OUT=OUT.resolve();OUT.mkdir(exist_ok=True)
rows=list(json.loads((ROOT/'_data/social-images.json').read_text())['pages'].values());F=ImageFont.truetype(str(ROOT/'assets/fonts/DM-Sans-Regular.ttf'),13)
def sheet(items,name,cols=4,tw=360):
 th=round(tw*630/1200);slot=th+45;out=Image.new('RGB',(cols*tw,math.ceil(len(items)/cols)*slot),'#f1ede6');d=ImageDraw.Draw(out)
 for i,row in enumerate(items):
  x=i%cols*tw;y=i//cols*slot;im=Image.open(ROOT/row['src'].lstrip('/'));im.thumbnail((tw,th));out.paste(im,(x,y));title=row['url'];parts=[title[j:j+int(tw/7)] for j in range(0,len(title),int(tw/7))]
  for j,s in enumerate(parts[:2]):d.text((x+7,y+th+5+j*17),s,font=F,fill='#583540')
 out.save(OUT/name,quality=94)
